description:
Parse a small tool's options from `argv` (with `argv[0]` the program's name):

```c
struct opts { int count; int verbose; const char *name; const char *file; };
int parse_opts(int argc, char **argv, struct opts *o, char *err, size_t err_size);
```

- defaults: `count` 10, `verbose` 0, `name` `"world"`, `file` `NULL`;
- `-n N` sets `count` (a whole number of 0 or more), `-v` sets `verbose`, `--name=TEXT` sets `name`;
- the first argument that does not start with `-` is the `file`; a second one is an error;
- `--` ends the options (what follows is the file, even if it starts with `-`);
- returns 0, or -1 after writing a message into `err` such as `-n needs a number`, `bad number: x`, `unknown option -q` or `more than one file`.

starter.solution.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct opts { int count; int verbose; const char *name; const char *file; };

int parse_opts(int argc, char **argv, struct opts *o, char *err, size_t err_size)
{
    o->count = 10;
    o->verbose = 0;
    o->name = "world";
    o->file = NULL;
    return 0;
}

solution.solution.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct opts { int count; int verbose; const char *name; const char *file; };

static int set_file(struct opts *o, const char *f, char *err, size_t err_size)
{
    if (o->file) {
        snprintf(err, err_size, "more than one file");
        return -1;
    }
    o->file = f;
    return 0;
}

int parse_opts(int argc, char **argv, struct opts *o, char *err, size_t err_size)
{
    o->count = 10;
    o->verbose = 0;
    o->name = "world";
    o->file = NULL;
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "--") == 0) {
            for (int j = i + 1; j < argc; j++)
                if (set_file(o, argv[j], err, err_size) != 0) return -1;
            return 0;
        } else if (strcmp(a, "-n") == 0) {
            if (i + 1 >= argc) {
                snprintf(err, err_size, "-n needs a number");
                return -1;
            }
            char *end;
            const char *v = argv[++i];
            long n = strtol(v, &end, 10);
            if (*v == '\0' || *end != '\0' || n < 0 || n > 1000000) {
                snprintf(err, err_size, "bad number: %s", v);
                return -1;
            }
            o->count = (int)n;
        } else if (strcmp(a, "-v") == 0) {
            o->verbose = 1;
        } else if (strncmp(a, "--name=", 7) == 0) {
            o->name = a + 7;
        } else if (a[0] == '-' && a[1] != '\0') {
            snprintf(err, err_size, "unknown option %s", a);
            return -1;
        } else if (set_file(o, a, err, err_size) != 0) {
            return -1;
        }
    }
    return 0;
}

unitTests:
TEST("defaults") { char *a[] = {"tool"}; struct opts o; char e[64]; CHECK_EQ(parse_opts(1, a, &o, e, sizeof e), 0); CHECK_EQ(o.count, 10); CHECK_EQ(o.verbose, 0); CHECK_STR(o.name, "world"); CHECK(o.file == NULL); }
TEST("every option") { char *a[] = {"tool", "-v", "-n", "3", "--name=Ada", "notes.txt"}; struct opts o; char e[64]; CHECK_EQ(parse_opts(6, a, &o, e, sizeof e), 0); CHECK_EQ(o.count, 3); CHECK_EQ(o.verbose, 1); CHECK_STR(o.name, "Ada"); CHECK_STR(o.file, "notes.txt"); }
TEST("double dash") { char *a[] = {"tool", "--", "-strange-name"}; struct opts o; char e[64]; CHECK_EQ(parse_opts(3, a, &o, e, sizeof e), 0); CHECK_STR(o.file, "-strange-name"); }
TEST("errors") { struct opts o; char e[64]; char *a1[] = {"tool", "-n"}; CHECK_EQ(parse_opts(2, a1, &o, e, sizeof e), -1); CHECK_STR(e, "-n needs a number"); char *a2[] = {"tool", "-n", "x"}; CHECK_EQ(parse_opts(3, a2, &o, e, sizeof e), -1); CHECK_STR(e, "bad number: x"); char *a3[] = {"tool", "-q"}; CHECK_EQ(parse_opts(2, a3, &o, e, sizeof e), -1); CHECK_STR(e, "unknown option -q"); char *a4[] = {"tool", "a.txt", "b.txt"}; CHECK_EQ(parse_opts(3, a4, &o, e, sizeof e), -1); CHECK_STR(e, "more than one file"); }

